---@class SResourcesPkHandler : SPacketHandlers
local ResourcesPkHandler = T(Global, "PacketHandlers")
---@type SResourcesMgr
local SResourcesMgr = T(Global, "SResourcesMgr")
---@type PidPacketSender : SPidPacketSender
local PidPacketSender = T(Global, "PidPacketSender")

function ResourcesPkHandler:onPlayerRecycleResources(packet)
    local customGame = T(Global, "customGame")
    if not customGame:checkOwner(self.userId) then
        return
    end
    if not self:checkCanAddItem(Define.ResourceItemId, 0, 1) then
        PidPacketSender:sendResourcesTip(self.userId, "gui.resources.is.full.inventory")
        return
    end
    self:addItem(Define.ResourceItemId, 1)
    SResourcesMgr:removeResources(packet.id)
end

function ResourcesPkHandler:onEditResources(packet)
    local customGame = T(Global, "customGame")
    if not customGame:checkOwner(self.userId) then
        return
    end
    local resources = SResourcesMgr:getResources(packet.resourcesId)
    if resources then
        resources:saveResources(packet.info)
    end
end

return ResourcesPkHandler